-- fix/play_again_queue.lua [PLAYQUEUE] 2026-10-25 (match places: Matchmaking + Ranked; the Tutorial gets it too, unused there).
-- GENERATED by tools/build_playqueue.py from fix/play_again_queue.tpl.lua + scripts/match/MatchmakingManager.lua: edit those.
-- Edward: "when you click play again in a matchmaking game it should add the same queue you have in the lobby to that game so
-- it would put you in queue; this queue pop up would be on your screen even during the victory or defeat screen, and once it
-- finds a game it will create a new matchmaking server for you with the person you are matched with instead of tping you to
-- the lobby".
--   1. The lobby's online matchmaker (MatchmakingManager: MemoryStore queues shared by every server, ReserveServer + MatchSpec +
--      TeleportAsync on a match) is installed in the match place's Managers (ModuleLoader starts it). Same code as the hub's.
--   2. RoundManager: MatchFlow "PlayAgain" (results card, after-match panel, PLAY AGAIN row) calls its FindMatch for this
--      match's queue (parties: the leader queues everyone; a member goes alone as before); pressing it again while searching
--      cancels. It also works while the results show. No online queue here (offline place): the old hub AutoQueue hop.
--      Rematch starting cancels any search; To Hub cancels yours first; when the after-match time runs out, players still
--      searching stay until they are matched or cancel (the rest go to the hub as before).
--   UI (ui/, deployed with the place's UI): match/QueuePill.client.lua (the lobby's Searching pill above every match screen),
--   DuelHUD's Play Again buttons follow MM_Status, LobbyHud hides its own pill in match places.
-- Idempotent; checks every edit first; UNDO swaps the RoundManager edits back and removes the module.
local UNDO = false --@UNDO
local IS_LOBBY = workspace:FindFirstChild("LobbyMap") ~= nil and game:GetService("ReplicatedStorage"):FindFirstChild("PlaceKind") == nil
assert(not IS_LOBBY, "PLAYQUEUE is for the match places (the hub has its own MatchmakingManager)")
local SSS = game:GetService("ServerScriptService")
local M = SSS.ServerScripts["[Server] Init"].GameManager.Managers
local RM = M:FindFirstChild("RoundManager")
assert(RM, "no RoundManager")
local out = {}

-- 1. the matchmaker module
local MM_SRC = [=====[__MMSRC__]=====]
local mm = M:FindFirstChild("MatchmakingManager")
if UNDO then
	if mm and mm:GetAttribute("PlayQueue") then mm:Destroy(); table.insert(out, "module -") else table.insert(out, "module =") end
else
	assert(loadstring(MM_SRC), "MatchmakingManager source would not parse")
	if not mm then
		mm = Instance.new("ModuleScript")
		mm.Name = "MatchmakingManager"
		mm:SetAttribute("PlayQueue", true)
		mm.Source = MM_SRC
		mm.Parent = M
		table.insert(out, "module +")
	elseif mm.Source ~= MM_SRC then
		assert(mm:GetAttribute("PlayQueue"), "a MatchmakingManager that PLAYQUEUE didn't install is already here")
		mm.Source = MM_SRC
		table.insert(out, "module ~")
	else
		table.insert(out, "module =")
	end
end

-- 2. RoundManager
local HELPERS = [==[
-- [PLAYQUEUE] (Edward 2026-10-25) Play Again queues you from THIS server with the lobby's online queue (MatchmakingManager is
-- installed in the match places): the Searching pill shows over the results and the after-match lobby, and a match found
-- teleports you straight into a new reserved match server with the players you were matched with (no hub hop). Pressing it
-- again while searching cancels. No online queue here (an offline place): the old hub AutoQueue hop (playAgain).
local function mmRemotes()
	local ok, R = pcall(function() return require(ServerScriptService.Lobby.LobbyRemotes) end)
	return (ok and R and R.Handlers and R.Handlers.FindMatch) and R or nil
end
local function mmCancel(player: Player)
	local R = mmRemotes()
	if R and R.Handlers.CancelMatch and player:GetAttribute("MM_Status") == "Searching" then pcall(R.Handlers.CancelMatch, player) end
end
local function queueAgain(player: Player, qid: string)
	local R = mmRemotes()
	if not R then playAgain(player, qid) return end
	local mmSt = player:GetAttribute("MM_Status")
	if mmSt == "Searching" then
		local ok, res = pcall(R.Handlers.CancelMatch, player)
		if ok and type(res) == "table" and res.msg and R.Notify then R.Notify(player, res.msg, res.ok and "info" or "bad") end
		return
	elseif mmSt ~= nil then
		return -- Found / Teleporting: already on the way
	end
	-- a party member who isn't the leader goes alone (as the hub Play Again did); the leader queues the whole party
	local PS = partyService()
	local party = PS and PS.Of(player)
	if party and #party.members > 1 and party.leader ~= player then PS.Leave(player, "left") end
	local ok, res = pcall(R.Handlers.FindMatch, player, qid)
	if ok and type(res) == "table" and res.offline then playAgain(player, qid) return end
	if not ok then warn("[RoundManager] [PLAYQUEUE] FindMatch failed: " .. tostring(res)) playAgain(player, qid) return end
	if type(res) == "table" and not res.ok and res.msg and R.Notify then R.Notify(player, res.msg, "bad") end
end
]==]

local edits = {
	{ "local function postMatchFlow(player: Player, kind: string)\n",
		HELPERS .. "\nlocal function postMatchFlow(player: Player, kind: string)\n" },
	{ "\tif not (s and (s.inPost or (kind == \"Rematch\" and ended))) then return end\n",
		"\t-- [PLAYQUEUE] Play Again works while the results show too (the search pill rides over Victory / Defeat)\n"
		.. "\tif not (s and (s.inPost or ((kind == \"Rematch\" or kind == \"PlayAgain\") and ended))) then return end\n" },
	{ "\telseif kind == \"ToHub\" then\n\t\tplayer:SetAttribute(\"InPseudoLobby\", nil)\n",
		"\telseif kind == \"ToHub\" then\n"
		.. "\t\tif player:GetAttribute(\"MM_Status\") ~= nil and player:GetAttribute(\"MM_Status\") ~= \"Searching\" then return end -- [PLAYQUEUE] matched: on the way\n"
		.. "\t\tmmCancel(player) -- [PLAYQUEUE] leave the online queue first\n"
		.. "\t\tplayer:SetAttribute(\"InPseudoLobby\", nil)\n" },
	{ "\t\tplayAgain(player, queueIdOf(s.first)) -- [PSEUDOLOBBY] parties go together\n",
		"\t\tqueueAgain(player, queueIdOf(s.first)) -- [PLAYQUEUE] queue from here (was playAgain: the hub hop)\n" },
	{ "\t\tif os.clock() - t0 > (C.PostMatchTime or 300) then\n\t\t\tbackToLobby(Players:GetPlayers())\n\t\t\tresult = \"timeout\"\n\t\t\tbreak\n\t\tend\n",
		"\t\tif os.clock() - t0 > (C.PostMatchTime or 300) then\n"
		.. "\t\t\t-- [PLAYQUEUE] players still in the online queue stay until they're matched (or cancel); everyone else goes to the hub\n"
		.. "\t\t\ts.sentHome = s.sentHome or {}\n"
		.. "\t\t\tlocal home, waiting = {}, 0\n"
		.. "\t\t\tfor _, p in Players:GetPlayers() do\n"
		.. "\t\t\t\tif p:GetAttribute(\"MM_Status\") ~= nil then waiting += 1\n"
		.. "\t\t\t\telseif not s.sentHome[p] then s.sentHome[p] = true; table.insert(home, p) end\n"
		.. "\t\t\tend\n"
		.. "\t\t\tif #home > 0 then backToLobby(home) end\n"
		.. "\t\t\tif waiting == 0 then\n"
		.. "\t\t\t\tresult = \"timeout\"\n"
		.. "\t\t\t\tbreak\n"
		.. "\t\t\tend\n"
		.. "\t\tend\n" },
	{ "\t\t\tif still then result = \"rematch\" break end\n",
		"\t\t\tif still then\n"
		.. "\t\t\t\tfor _, p in Players:GetPlayers() do mmCancel(p) end -- [PLAYQUEUE] a rematch takes everyone out of the online queue\n"
		.. "\t\t\t\tresult = \"rematch\"\n"
		.. "\t\t\t\tbreak\n"
		.. "\t\t\tend\n" },
}
local s = RM.Source:gsub("\r\n", "\n")
for i, e in edits do
	local o, n = e[1], e[2]
	if UNDO then o, n = n, o end
	local done
	if UNDO then done = not s:find(o, 1, true) else done = s:find(n, 1, true) ~= nil end
	if done then
		table.insert(out, i .. "=")
	else
		local a, b = s:find(o, 1, true)
		assert(a, "RoundManager edit " .. i .. " anchor not found")
		assert(not s:find(o, b + 1, true), "RoundManager edit " .. i .. " anchor not unique")
		s = s:sub(1, a - 1) .. n .. s:sub(b + 1)
		table.insert(out, i .. "+")
	end
end
local f, err = loadstring(s)
assert(f, "RoundManager would not parse: " .. tostring(err))
if RM.Source ~= s then RM.Source = s end
return "PLAYQUEUE " .. table.concat(out, " ")
